Pseudocode (Phaser.js):
// In update loop: check for jump input and on-ground status
if (cursors.up.isDown && player.body.onFloor()) {
    player.setVelocityY(-300);  // give the player an upward velocity
}

// If using variable jump height (optional):
if (!cursors.up.isDown && player.body.velocity.y < 0) {
    // cut the jump short if jump key released early
    player.body.velocity.y *= 0.5;
}

// In player's state, track jumps count
if (player.body.onFloor()) {
    player.jumps = 0;
}

// On jump key press
if (cursors.up.justDown) {
    if (player.body.onFloor()) {
        // Normal jump
        player.setVelocityY(-300);
        player.jumps = 1;
    } else if (player.jumps < 2) {
        // Double jump
        player.setVelocityY(-300);
        player.jumps++;
    }
}

// In update: detect wall contact
let onLeftWall = player.body.touching.left;
let onRightWall = player.body.touching.right;

if (cursors.up.isDown && (onLeftWall || onRightWall)) {
    // Jump off the wall
    player.setVelocityY(-300);
    if (onLeftWall) {
        player.setVelocityX(200);  // jump to the right
    } else if (onRightWall) {
        player.setVelocityX(-200); // jump to the left
    }
    // Optionally, prevent immediate re-wall-jumping by a short delay or reset jump count
}

// In update: if pressing towards wall and falling
if ((onLeftWall && cursors.left.isDown) || (onRightWall && cursors.right.isDown)) {
    if (player.body.velocity.y > 50) {
        player.body.velocity.y = 50;  // cap the fall speed while sliding
    }
    // Optionally, set a wall slide animation here
}

// On dash input (for example, pressing a dash key)
if (Phaser.Input.Keyboard.JustDown(dashKey) && canDash) {
    canDash = false;
    player.setVelocityX(player.facing === 'right' ? 600 : -600);
    // Optionally, make the player briefly invincible or unaffected by gravity
    player.body.allowGravity = false;
    this.time.delayedCall(200, () => {
        // End dash after 200ms
        player.body.allowGravity = true;
        player.setVelocityX(0);
        // Restore normal gravity and control
    });
    // Set a cooldown for the next dash
    this.time.delayedCall(1000, () => { canDash = true; });
}

// On slide input (e.g., down arrow while running)
if (cursors.down.isDown && player.body.onFloor() && Math.abs(player.body.velocity.x) > 0) {
    playerSliding = true;
    // Reduce player collider height for the slide duration
    player.body.setSize(player.width, player.height / 2);
    // Give a burst of speed if not already fast
    player.setVelocityX(player.facing === 'right' ? 400 : -400);
    // After slide duration, reset player state
    this.time.delayedCall(500, () => {
        playerSliding = false;
        player.body.setSize(player.width, player.height); // reset size
    });
}

// Activate flight mode (for instance, on picking up a power-up or holding a fly key)
player.body.allowGravity = false;

// In update loop, when flying:
if (cursors.up.isDown) {
    player.setVelocityY(-200);  // move up
} else if (cursors.down.isDown) {
    player.setVelocityY(200);   // move down
} else {
    player.setVelocityY(0);
}

// Horizontal movement remains similar to walking
if (cursors.left.isDown) {
    player.setVelocityX(-200);
} else if (cursors.right.isDown) {
    player.setVelocityX(200);
}

// To disable flight (out of fuel or landing):
player.body.allowGravity = true;

// Check overlap with ladder
this.physics.add.overlap(player, ladder, () => {
    player.onLadder = true;
    player.body.allowGravity = false;
    player.setVelocityX(0); // lock horizontal movement while on ladder
});

// In update: if on ladder, allow vertical movement
if (player.onLadder) {
    if (cursors.up.isDown) {
        player.setVelocityY(-100);
    } else if (cursors.down.isDown) {
        player.setVelocityY(100);
    } else {
        player.setVelocityY(0);
    }
    // If jump is pressed or ladder ends, get off the ladder
    if (cursors.up.isDown && Phaser.Input.Keyboard.JustDown(jumpKey)) {
        player.onLadder = false;
        player.body.allowGravity = true;
        player.setVelocityY(-300); // jump off ladder
    }
}

// If player reaches top or bottom of ladder or moves away:
if (!player.body.touching.ladder && player.onLadder) {
    player.onLadder = false;
    player.body.allowGravity = true;
}

// When player enters water zone
this.physics.add.overlap(player, waterLayer, () => {
    player.inWater = true;
    player.body.setDrag(100);      // increase drag to simulate water resistance
    player.body.setGravityY(100);  // reduce gravity effect
});

// When in water, adjust controls
if (player.inWater) {
    if (cursors.up.isDown) {
        player.setVelocityY(-100); // swim upward
    } else if (cursors.down.isDown) {
        player.setVelocityY(100);  // dive downward
    }
    // Horizontal movement is slower in water
    if (cursors.left.isDown) {
        player.setVelocityX(-100);
    } else if (cursors.right.isDown) {
        player.setVelocityX(100);
    }
}

// On leaving water
this.physics.add.overlap(player, landExit, () => {
    player.inWater = false;
    player.body.setDrag(0);
    player.body.setGravityY(300); // restore normal gravity
});

// On crouch key down
if (cursors.down.isDown && player.body.onFloor()) {
    player.isCrouching = true;
    player.body.setSize(player.width, player.height * 0.5); // half height
    player.setVelocityX(0); // usually stop horizontal movement when crouching
}

// On releasing crouch
if (player.isCrouching && cursors.down.isUp) {
    // Before standing, check if space above is clear (pseudo-code):
    if (spaceAboveIsClear(player)) {
        player.isCrouching = false;
        player.body.setSize(player.width, player.height); // restore full height
    }
}

// Drop through platform (one-way platforms) example:
if (player.isCrouching && Phaser.Input.Keyboard.JustDown(jumpKey)) {
    platformCollider.active = false; // temporarily disable collision
    this.time.delayedCall(200, () => { platformCollider.active = true; });
}

// On attack input
if (Phaser.Input.Keyboard.JustDown(attackKey)) {
    player.play('attackAnimation');
    // Create or enable attack hitbox in front of player
    let hitbox = playerAttackHitbox;
    hitbox.x = player.x + (player.facing === 'right' ? 20 : -20);
    hitbox.y = player.y;
    hitbox.active = true;
    // Disable hitbox after a short window
    this.time.delayedCall(200, () => { hitbox.active = false; });
}

// Collision detection (set up in create):
this.physics.add.overlap(playerAttackHitbox, enemies, (hitbox, enemy) => {
    if (hitbox.active) {
        enemy.health -= player.attackDamage;
        enemy.play('hitReaction');
        if (enemy.health <= 0) {
            enemy.destroy();
        }
    }
});

// On ranged attack input
if (Phaser.Input.Keyboard.JustDown(shootKey)) {
    // Create a projectile at player's position
    let bullet = bulletsGroup.create(player.x, player.y, 'bulletSprite');
    bullet.setVelocityX(player.facing === 'right' ? 600 : -600);
}

// Projectile-Enemy collision (setup once in create)
this.physics.add.overlap(bulletsGroup, enemies, (bullet, enemy) => {
    enemy.health -= player.rangedDamage;
    bullet.destroy(); // remove projectile on hit
    if (enemy.health <= 0) {
        enemy.destroy();
    }
});

// If projectiles should be limited by ammo:
if (player.ammo > 0) {
    player.ammo--;
    // else, prevent shooting if no ammo
}

// On parry input
if (Phaser.Input.Keyboard.JustDown(parryKey) && !player.isParrying) {
    player.isParrying = true;
    player.play('parryStance');
    // Set a timer for parry active window
    this.time.delayedCall(300, () => {
        player.isParrying = false;
    });
}

// In enemy attack collision logic:
this.physics.add.overlap(player, enemyAttackHitboxes, (playerSprite, attackHitbox) => {
    if (player.isParrying) {
        // Successful parry
        attackHitbox.active = false; // negate the attack
        let enemy = attackHitbox.owner;
        enemy.stunned = true;
        enemy.play('stunnedAnimation');
        // Optionally deal counter damage or knockback to enemy
        enemy.health -= player.parryCounterDamage;
    } else {
        // Player gets hit normally (apply damage)
        player.health -= attackHitbox.damage;
    }
});

// On dodge input (e.g., pressing a dodge key)
if (Phaser.Input.Keyboard.JustDown(dodgeKey) && !player.isDodging) {
    player.isDodging = true;
    player.invulnerable = true;
    // Perform a quick roll in facing direction
    let dodgeDistance = player.facing === 'right' ? 50 : -50;
    this.tweens.add({
        targets: player,
        x: player.x + dodgeDistance,
        duration: 200,
        onComplete: () => {
            // End dodge
            player.isDodging = false;
            // Delay turning off invulnerability slightly to cover entire roll
            this.time.delayedCall(100, () => { player.invulnerable = false; });
        }
    });
}

// On block button down
if (blockKey.isDown) {
    player.isBlocking = true;
    player.play('blockPose');
} else {
    player.isBlocking = false;
}

// In enemy hit detection:
this.physics.add.overlap(player, enemyAttackHitboxes, (playerSprite, attackHitbox) => {
    if (player.isBlocking) {
        // Block the attack: reduce or nullify damage
        player.stamina -= attackHitbox.damage * 0.5; // example: reduce stamina
        // possibly play block spark animation
    } else {
        // Take full damage
        player.health -= attackHitbox.damage;
    }
});

// Simplified combo logic
let comboStep = 0;
let comboTimer;

function attack() {
    if (comboStep === 0) {
        player.play('attack1');
    } else if (comboStep === 1) {
        player.play('attack2');
    } else if (comboStep === 2) {
        player.play('attack3');
    }
    comboStep = (comboStep + 1) % 3;
    // reset combo if no further input
    if (comboTimer) comboTimer.remove(false);
    comboTimer = this.time.delayedCall(500, () => { comboStep = 0; });
}

if (Phaser.Input.Keyboard.JustDown(attackKey)) {
    attack();
}

// Example: Player interacts with shop NPC
if (Phaser.Input.Keyboard.JustDown(interactKey) && checkOverlap(player, shopKeeper)) {
    showShopMenu(); // display shop UI
    game.scene.pause(); // pause gameplay if needed
}

// In shop menu logic:
function purchaseItem(item) {
    if (player.coins >= item.price) {
        player.coins -= item.price;
        giveItemToPlayer(item);
        playSound('purchase');
    } else {
        playSound('error'); // not enough money
    }
}

// Example: player picks up a max health increase item
this.physics.add.overlap(player, healthUpgradeItem, () => {
    player.maxHealth += 20;
    player.health = player.maxHealth; // heal to full on pickup
    healthUpgradeItem.destroy();
});

// Example: player buys an attack upgrade from shop
function buyAttackUpgrade() {
    if (player.coins >= upgradeCost) {
        player.coins -= upgradeCost;
        player.attackPower += 5;
    }
}

// Example: picking up an item
this.physics.add.overlap(player, itemSprite, (playerSprite, itemSprite) => {
    addToInventory(itemSprite.itemData);
    itemSprite.destroy();
});

function addToInventory(item) {
    // item could have properties like item.name, item.quantity
    player.inventory.push(item);
    updateInventoryUI();
}

// Using an item (e.g., health potion)
function useItem(itemName) {
    let index = player.inventory.findIndex(it => it.name === itemName);
    if (index !== -1) {
        let item = player.inventory[index];
        if (item.name === 'Health Potion') {
            player.health = Math.min(player.maxHealth, player.health + 50);
        }
        item.quantity -= 1;
        if (item.quantity <= 0) {
            player.inventory.splice(index, 1);
        }
        updateInventoryUI();
    }
}

// Example: speed boost power-up
this.physics.add.overlap(player, speedBoostItem, () => {
    speedBoostItem.destroy();
    player.speed *= 2;  // double the player's speed
    playSound('powerup');
    // Set a timer to end the effect after 5 seconds
    this.time.delayedCall(5000, () => {
        player.speed /= 2; // revert to normal speed
    });
});

// Example: invincibility power-up
this.physics.add.overlap(player, invincibilityItem, () => {
    invincibilityItem.destroy();
    player.invulnerable = true;
    this.time.delayedCall(3000, () => {
        player.invulnerable = false;
    });
});

// Ammo usage
if (Phaser.Input.Keyboard.JustDown(shootKey) && player.ammo > 0) {
    player.ammo--;
    shootProjectile();
    if (player.ammo === 0) {
        clickEmptyGunSound.play();
    }
}

// Reload mechanic
if (Phaser.Input.Keyboard.JustDown(reloadKey) && player.ammo < player.maxAmmo) {
    player.reloading = true;
    player.play('reloadAnimation');
    this.time.delayedCall(1000, () => {
        player.ammo = player.maxAmmo;
        player.reloading = false;
    });
}

// Ammo pickup
this.physics.add.overlap(player, ammoPickup, () => {
    player.ammo = Math.min(player.maxAmmo, player.ammo + ammoPickup.amount);
    ammoPickup.destroy();
});

// Example pseudo-recipe
const recipes = {
    'health_potion': { herb: 2, water: 1 }
};

function craft(itemName) {
    let recipe = recipes[itemName];
    if (recipe && hasMaterials(recipe)) {
        // remove materials from inventory
        for (let material in recipe) {
            player.inventory[material] -= recipe[material];
        }
        // add crafted item
        player.inventory[itemName] = (player.inventory[itemName] || 0) + 1;
        playSound('craftSuccess');
    } else {
        playSound('craftFail');
    }
}

function hasMaterials(recipe) {
    for (let material in recipe) {
        if (!player.inventory[material] || player.inventory[material] < recipe[material]) {
            return false;
        }
    }
    return true;
}

// Equipping an item (e.g., a new weapon)
function equipItem(item) {
    if (item.type === 'weapon') {
        player.equippedWeapon = item;
        player.attackDamage = item.attackValue;
        player.attackType = item.attackType;
    } else if (item.type === 'armor') {
        player.equippedArmor = item;
        player.defense = item.defenseValue;
    }
    updateEquipmentUI();
}

// Example inventory selection
if (Phaser.Input.Keyboard.JustDown(equipKey)) {
    let selectedItem = inventoryUI.getSelectedItem();
    equipItem(selectedItem);
}

// Initialize survival stats
player.hunger = 100;
player.thirst = 100;

// Every second, decrease hunger and thirst
this.time.addEvent({
    delay: 1000,
    loop: true,
    callback: () => {
        player.hunger = Math.max(0, player.hunger - 1);
        player.thirst = Math.max(0, player.thirst - 1);
        if (player.hunger === 0 || player.thirst === 0) {
            player.health -= 1; // lose health if starving or dehydrated
        }
    }
});

// Using food item to restore hunger
function eatFood(item) {
    player.hunger = Math.min(100, player.hunger + item.foodValue);
    removeItemFromInventory(item);
}

// Setting initial health
player.maxHealth = 100;
player.health = 100;

// On player hit by enemy
function onPlayerHit(damage) {
    if (!player.invulnerable) {
        player.health -= damage;
        player.invulnerable = true;
        // flash or blink player sprite to indicate hit
        this.time.delayedCall(1000, () => { player.invulnerable = false; });
        if (player.health <= 0) {
            playerDies();
        }
    }
}

// Health pickup example
this.physics.add.overlap(player, healthPack, () => {
    player.health = Math.min(player.maxHealth, player.health + 20);
    healthPack.destroy();
});

if (player.body.blocked.left || player.body.blocked.right) {
    if (cursors.up.isDown) {
        // Begin wall climb
        player.body.allowGravity = false;
        player.setVelocityY(-climbSpeed);
        player.anims.play('climb', true);
    } else if (cursors.down.isDown) {
        player.body.allowGravity = false;
        player.setVelocityY(climbSpeed);
        player.anims.play('climb', true);
    } else {
        // Stick to wall without moving (maybe slide slowly)
        player.setVelocityY(slideSpeed);
    }
} else {
    // Not on a wall, ensure gravity is normal
    player.body.allowGravity = true;
}

// Assuming use of Arcade physics for simplicity
if (grappleButton.isDown && !player.isGrappling) {
    let hookTarget = getGrappleTarget(player.x, player.y, aimAngle);
    if (hookTarget) {
        player.isGrappling = true;
        player.body.allowGravity = false;
        // Calculate direction vector toward target
        let dx = hookTarget.x - player.x;
        let dy = hookTarget.y - player.y;
        let dist = Math.sqrt(dx*dx + dy*dy);
        player.setVelocity(dx/dist * grappleSpeed, dy/dist * grappleSpeed);
        // Optionally create a rope line graphic
        ropeLine = this.add.line(0, 0, player.x, player.y, hookTarget.x, hookTarget.y, 0xFFFFFF);
    }
}
// Update rope line each frame if grappling
if (player.isGrappling) {
    ropeLine.setTo(player.x, player.y, hookTarget.x, hookTarget.y);
    // If player reached near the hook or presses jump to cancel
    if (Phaser.Math.Distance.Between(player.x, player.y, hookTarget.x, hookTarget.y) < 10 || cancelKey.isDown) {
        player.isGrappling = false;
        player.body.allowGravity = true;
        ropeLine.destroy();
    }
}

// In enemy update
if (!player.isHidden && Phaser.Math.Distance.Between(enemy.x, enemy.y, player.x, player.y) < enemy.visionRange) {
    if (hasLineOfSight(enemy, player)) {
        enemy.setAlert(true);
    }
}
// Toggling player hidden state
if (cursors.down.isDown && player.overlap(hidingSpot)) {
    player.isHidden = true;
    player.setTexture('player_hidden'); // change sprite to a crouching/hiding image
} else {
    player.isHidden = false;
    player.setTexture('player');
}
// Enemy reaction if alerted
if (enemy.alert) {
    enemy.chase(player);
    // maybe spawn an exclamation icon or play alert sound
}

// On player overlap with rope
this.physics.add.overlap(player, ropeEnd, () => {
    player.onRope = true;
    player.body.allowGravity = false;
    player.ropeAnchor = {x: ropeAnchor.x, y: ropeAnchor.y};
    player.swingAngle = Math.PI / 4; // starting angle
    player.swingSpeed = 0; // no initial angular velocity
});
// In update, if on rope, simulate swing
if (player.onRope) {
    // basic pendulum physics
    let length = Phaser.Math.Distance.Between(player.ropeAnchor.x, player.ropeAnchor.y, player.x, player.y);
    let gravityForce = 0.98; // some gravity constant for swing
    player.swingSpeed += (-gravityForce / length) * Math.sin(player.swingAngle);
    player.swingAngle += player.swingSpeed;
    // Update player position based on angle
    player.x = player.ropeAnchor.x + length * Math.sin(player.swingAngle);
    player.y = player.ropeAnchor.y + length * Math.cos(player.swingAngle);
    // If jump key pressed to release
    if (cursors.up.isDown) {
        player.onRope = false;
        player.body.allowGravity = true;
        // Apply momentum from swing to player velocity
        player.setVelocity(player.x - player.ropeAnchor.x, player.y - player.ropeAnchor.y);
    }
}

// Slow motion example
if (slowMoKey.isDown && !this.slowMoActive) {
    this.slowMoActive = true;
    this.physics.world.timeScale = 0.2;
    this.time.delayedCall(1000, () => {
        // restore normal speed after 1 second real-time (5 seconds game-time if timeScale=0.2)
        this.physics.world.timeScale = 1;
        this.slowMoActive = false;
    });
}
// Time rewind example (player only for simplicity)
stateBuffer.push({x: player.x, y: player.y, vx: player.body.velocity.x, vy: player.body.velocity.y});
if (rewindKey.isDown) {
    if (stateBuffer.length > 0) {
        let prevState = stateBuffer.pop();
        player.x = prevState.x;
        player.y = prevState.y;
        player.body.velocity.x = prevState.vx;
        player.body.velocity.y = prevState.vy;
    }
}
// (In a full implementation, you'd loop this rewind over a short duration and handle other objects similarly.)

// Magnetic boots example: stick to a ceiling
if (player.magnetActive && player.isNearMetalCeiling) {
    player.body.allowGravity = false;
    // pull upward
    player.setVelocityY(-50);
    // if reached ceiling
    if (player.y <= ceilingY + player.height/2) {
        player.y = ceilingY + player.height/2;
        player.body.velocity.y = 0;
    }
} else {
    player.body.allowGravity = true;
}
// Magnet gun example: pulling metal objects
metalGroup.getChildren().forEach(metal => {
    if (player.magnetActive) {
        let dx = player.x - metal.x;
        let dy = player.y - metal.y;
        let dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < magnetRange) {
            metal.body.velocity.x += (dx/dist) * magnetForce;
            metal.body.velocity.y += (dy/dist) * magnetForce;
        }
    }
});

// Portal teleportation
this.physics.add.overlap(player, portals, (player, portal) => {
    if (!player.justTeleported) {
        let destination = portals.find(p => p.id === portal.targetId);
        if (destination) {
            player.setPosition(destination.x, destination.y);
            player.justTeleported = true;
            // Prevent immediate re-trigger
            this.time.delayedCall(500, () => { player.justTeleported = false; });
        }
    }
});
// Blink ability
if (blinkKey.isDown && player.canBlink) {
    let targetX = player.x + blinkDistance * (player.facingRight ? 1 : -1);
    // Check if target is free (no wall)
    if (!tileLayer.hasTileAtWorldXY(targetX, player.y)) {
        // Teleport player
        let oldX = player.x, oldY = player.y;
        player.setPosition(targetX, player.y);
        // Play teleport effects
        playTeleportEffect(oldX, oldY);
        playTeleportEffect(player.x, player.y);
        player.canBlink = false;
        this.time.delayedCall(1000, () => { player.canBlink = true; });
    }
}

