    player.setVelocityX(player.body.velocity.x * 1.2);
    // use a timer or condition to end slide after a short duration
    this.time.delayedCall(500, () => {
        // restore collider size
        player.setSize(player.width, player.height);
    });
}

// On dodge key press:
if (dodgeKey.justDown && !player.isDodging) {
    player.isDodging = true;
    // give a burst of velocity (e.g., horizontally)
    let dodgeDirection = player.flipX ? -1 : 1;
