    player.body.setGravityY(600);
}

// While in water and boost active:
if (player.isSubmerged && boostKey.isDown && player.boostFuel > 0) {
    player.setVelocityX(player.body.velocity.x + 20);
    player.setVelocityY(player.body.velocity.y - 20);
