} else {
    // normal swimming control
    player.setVelocityX(0);
    player.setVelocityY(0);
}

// Regenerate fuel slowly when not boosting
if (!boostKey.isDown) {
    player.boostFuel = Math.min(player.boostFuel + 0.1, player.maxBoostFuel);
}

// On mount input:
if (mountKey.justDown && !player.isMounted && isMountNearby) {
