    if (!heavyAttackKey.isDown) {
        // on release
        let damage = Math.min(player.chargeTime / 100, 20); // cap at 20
        performHeavyAttack(damage);
        player.isCharging = false;
        player.chargeTime = 0;
    }
}

// On attack input:
if (attackKey.justDown) {
    if (player.comboStep < comboMoves.length && timeSinceLastAttack < comboWindow) {
        player.comboStep++;
        player.playAnimation(comboMoves[player.comboStep]);
        // deal damage accordingly
    } else {
        // reset combo or start from step 1
        player.comboStep = 1;
    }
    player.lastAttackTime = currentTime;
}

// Reset if too long since last input
if (currentTime - player.lastAttackTime > comboWindow) {
    player.comboStep = 0;
}

// On ranged shot input:
if (shootKey.justDown && player.ammo > 0) {
    let projectile = this.physics.add.sprite(player.x, player.y, 'bullet');
    projectile.setVelocityX(400 * player.direction);
    this.physics.add.collider(projectile, enemy, () => {
        enemy.takeDamage(10);
        projectile.destroy();
    });
    player.ammo--;
}

// On spell cast input:
if (castKey.justDown && player.mana >= spellCost && !player.spellOnCooldown) {
    player.mana -= spellCost;
    player.spellOnCooldown = true;
    // spawn spell effect
    let fireball = this.physics.add.sprite(player.x, player.y, 'fireball');
    fireball.setVelocity(300 * player.direction, 0);
    this.time.delayedCall(spellCooldown, () => {
        player.spellOnCooldown = false;
    });
}

// On AoE cast:
if (aoeKey.justDown && player.mana >= aoeCost) {
    player.mana -= aoeCost;
    let explosionRadius = 100;
    // find all enemies in range
    enemies.forEach(enemy => {
        if (Phaser.Math.Distance.Between(player.x, player.y, enemy.x, enemy.y) < explosionRadius) {
            enemy.takeDamage(20);
        }
    });
