}

// On summon input:
if (summonKey.justDown && player.mana >= summonCost) {
    player.mana -= summonCost;
    let summon = this.physics.add.sprite(player.x + 20, player.y, 'summonCreature');
    summon.health = 50;
    summon.behavior = followAndAttack;
    // Summon AI or movement pattern
}

// On mode switch:
if (switchModeKey.justDown) {
    player.weaponModeIndex = (player.weaponModeIndex + 1) % weaponModes.length;
    player.currentWeaponMode = weaponModes[player.weaponModeIndex];
}

// On fire:
if (fireKey.isDown) {
    fireWeapon(player.currentWeaponMode);
}

// On grab input:
if (grabKey.justDown && enemyInRange) {
    player.isGrabbing = true;
    grabbedEnemy = enemy;
}

// On throw input:
if (player.isGrabbing && throwKey.justDown) {
    player.isGrabbing = false;
    grabbedEnemy.setVelocityX(300 * player.direction);
