}

// Keep grabbed enemy’s position:
if (player.isGrabbing) {
    grabbedEnemy.x = player.x;
    grabbedEnemy.y = player.y;
}

// On takedown input:
if (takedownKey.justDown && player.isSneaking && behindEnemy(enemy)) {
