}

// On attack collision:
if (checkOverlap(player.weaponHitbox, enemy.weakPoint)) {
    enemy.takeDamage(baseDamage * 2);
} else {
    enemy.takeDamage(baseDamage);
}

// Check if enemy is in finisher state:
if (enemy.health < 20 && enemy.isStaggered && finisherKey.justDown) {
