    player.isPerformingFinisher = true;
    // play finishing move animation
    this.time.delayedCall(1000, () => {
        enemy.takeDamage(enemy.health); // kill
        player.isPerformingFinisher = false;
    });
}

// On spread shot input:
if (spreadShotKey.justDown) {
    for (let i = -2; i <= 2; i++) {
        let angleOffset = i * 5; // spread angle
        let bullet = this.physics.add.sprite(player.x, player.y, 'pellet');
        bullet.setVelocity(
            400 * Math.cos(Phaser.Math.DegToRad(angleOffset)),
            400 * Math.sin(Phaser.Math.DegToRad(angleOffset))
        );
    }
}

// On bullet collision:
this.physics.add.overlap(bullet, enemy.headCollider, () => {
    enemy.takeDamage(baseDamage * 2);
    bullet.destroy();
});

// If it hits the body:
this.physics.add.overlap(bullet, enemy.bodyCollider, () => {
    enemy.takeDamage(baseDamage);
    bullet.destroy();
});

// On hit:
if (player.weaponElement === 'fire') {
    enemy.takeDamage(baseDamage + fireBonus);
