    applyStatusEffect(enemy, 'burning');
} else if (player.weaponElement === 'ice') {
    enemy.takeDamage(baseDamage + iceBonus);
    enemy.slowMovement(2); // slow speed for 2s
}

// Each shot:
player.weaponHeat += 10;

if (player.weaponHeat >= 100) {
    player.isOverheated = true;
    // disable firing
}

// Cooling:
if (player.isOverheated) {
    player.weaponHeat -= 0.5;
    if (player.weaponHeat <= 0) {
        player.isOverheated = false;
        player.weaponHeat = 0;
    }
} else {
    // normal cooling
    player.weaponHeat = Math.max(player.weaponHeat - 0.1, 0);
}

// On lightning hit:
function chainLightning(currentTarget, chainCount) {
    if (chainCount <= 0) return;

    let nextTarget = findClosestEnemy(currentTarget, 200);
    if (nextTarget) {
        nextTarget.takeDamage(10);
        chainLightning(nextTarget, chainCount - 1);
    }
}

// Initial cast:
if (lightningSpellHit) {
