}

// On stance toggle:
if (defenseStanceKey.justDown && !player.isInDefensiveStance) {
    player.isInDefensiveStance = true;
    player.defenseMultiplier = 0.5; // half damage taken
    player.moveSpeed *= 0.8;
} else if (defenseStanceKey.justDown && player.isInDefensiveStance) {
