    }
}

// On player creation:
player.armorValue = 0.8; // 20% damage reduction
player.armorDurability = 100;

// On hit:
function onPlayerHit(damage) {
    let finalDamage = damage;
    if (player.armorDurability > 0) {
        finalDamage = damage * player.armorValue;
        player.armorDurability -= Math.ceil(damage * 0.1);
    }
    // ensure durability doesn't go below zero
    player.armorDurability = Math.max(player.armorDurability, 0);
    player.takeDamage(finalDamage);
}

// On hit with element:
function onPlayerHit(damage, elementType) {
    let finalDamage = damage;
    if (player.elementalResistances[elementType]) {
        let resist = player.elementalResistances[elementType]; // e.g., 0.3 for 30% reduction
        finalDamage = damage * (1 - resist);
    }
    player.takeDamage(finalDamage);
}

// Example usage:
player.elementalResistances = {
