player.shield -= damage;

// In update loop:
if (player.shield < player.maxShield) {
    player.shieldTimer += delta;
    if (player.shieldTimer > 3000) { // 3 seconds after last hit
        player.shield += regenRate * delta;
        player.shield = Math.min(player.shield, player.maxShield);
    }
}

// Shield usage when hit:
function onPlayerHit(damage) {
    if (player.shield > 0) {
        // shield absorbs damage first
        let remainder = Math.max(0, damage - player.shield);
        player.shield = Math.max(0, player.shield - damage);
        if (remainder > 0) {
            player.health -= remainder;
        }
        player.shieldTimer = 0; // reset timer
    } else {
        // no shield left, damage health
        player.health -= damage;
    }
}

// On cover input:
if (coverKey.justDown && isNearCoverObject(cover)) {
    player.isInCover = true;
    player.x = cover.coverSpot.x;
