// Calculate lead:
function getLeadPoint(playerPos, targetPos, targetVel, projectileSpeed) {
    // approximate intercept solution
    // iterative or simplified formula for leading
    // example: t = distance / projectileSpeed
    // adjust for targetVel
    let dx = targetPos.x - playerPos.x;
    let dy = targetPos.y - playerPos.y;
    let dist = Math.sqrt(dx*dx + dy*dy);
    let travelTime = dist / projectileSpeed;
    // predicted position:
    let predictedX = targetPos.x + targetVel.x * travelTime;
    let predictedY = targetPos.y + targetVel.y * travelTime;
    return { x: predictedX, y: predictedY };
}

// Show leading reticle at predicted point
