// On successful poison/bleed application:
function applyPoison(target, damagePerTick, duration) {
  target.isPoisoned = true;
  target.poisonTimer = 0;
  target.poisonDamage = damagePerTick;
  target.poisonDuration = duration; // in milliseconds
}

// In update loop:
if (target.isPoisoned) {
  target.poisonTimer += delta;
  if (target.poisonTimer >= poisonTickRate) {
    target.health -= target.poisonDamage;
    target.poisonTimer = 0;
    target.poisonDuration -= poisonTickRate;
  }
  if (target.poisonDuration <= 0 || target.health <= 0) {
    target.isPoisoned = false;
  }
}

// On hit with fire-based attack:
function igniteTarget(target, burnDamage, burnDuration) {
  target.isBurning = true;
