}

// In update loop:
if (target.isBurning) {
  target.burnTimer += delta;
  if (target.burnTimer >= burnTickRate) {
    target.health -= target.burnDamage;
    target.burnTimer = 0;
    target.burnDuration -= burnTickRate;
    // optional: check for flammable objects nearby
  }
  if (target.burnDuration <= 0) {
