  if (target.stunTime <= 0) {
    target.isStunned = false;
  }
}

// On freeze/slow effect:
function applyFreezeSlow(target, slowFactor, duration) {
  target.isSlowed = true;
  target.slowTimer = duration;
  target.originalSpeed = target.moveSpeed;
  target.moveSpeed *= slowFactor; // e.g., 0 = freeze, 0.5 = half speed
}

// In update:
if (target.isSlowed) {
  target.slowTimer -= delta;
  if (target.slowTimer <= 0) {
    target.isSlowed = false;
    target.moveSpeed = target.originalSpeed;
  }
}

// On mind control cast:
function applyMindControl(target, duration) {
  target.isCharmed = true;
  target.charmTimer = duration;
  target.allegiance = 'player'; // or set a flag that changes AI
}

// In enemy AI update:
if (target.isCharmed) {
