}

// On debuff application:
function applyDebuff(target, debuffType, amount, duration) {
  // example: defense down
  if (debuffType === 'defenseDown') {
    target.defense *= (1 - amount); // reduce defense
  }
  target.debuffTimer = duration;
  target.hasDebuff = true;
}

// In update:
if (target.hasDebuff) {
  target.debuffTimer -= delta;
  if (target.debuffTimer <= 0) {
