function addItemToSlot(item) {
  // find first empty slot or slot with same item if stackable
  for (let slot of player.inventory) {
    if (slot.item === item.id && item.stackable) {
      slot.quantity += item.quantity;
      return;
    } else if (!slot.item) {
      slot.item = item.id;
      slot.quantity = item.quantity;
      return;
    }
  }
  // if no slot found, inventory is full
}

// On item pickup:
function addItemWithWeight(item) {
  let totalWeight = getTotalInventoryWeight();
  if (totalWeight + item.weight <= player.maxCarryWeight) {
    player.inventory.push(item);
  } else {
    // can't pick up or apply encumbrance penalty
    if (!player.isEncumbered) {
      player.isEncumbered = true;
      player.moveSpeed *= 0.5;
    }
  }
}

function getTotalInventoryWeight() {
  let weight = 0;
  player.inventory.forEach(it => {
    weight += (it.weight * it.quantity);
  });
  return weight;
}

// Example 2D inventory layout:
