function placeItemInGrid(item) {
  // find space in inventoryGrid for item shape
  for (let row = 0; row < inventoryGrid.height; row++) {
    for (let col = 0; col < inventoryGrid.width; col++) {
      if (checkSpace(col, row, item.width, item.height)) {
        occupySpace(col, row, item);
        return true;
      }
    }
  }
  return false; // no space
}

