// On applying a global buff:
function applyGlobalBuff(buff) {
  for (let entity of allEntitiesInZone) {
    entity.activeBuffs.push({...buff});
  }
}

// In update:
for (let buff of entity.activeBuffs) {
  buff.duration -= delta;
  if (buff.duration <= 0) {
    removeBuff(entity, buff);
  }
}

// On skill use:
function useSkill(skill) {
  if (!skill.onCooldown && player.mana >= skill.manaCost) {
    player.mana -= skill.manaCost;
    skill.onCooldown = true;
    skill.cooldownTimer = skill.cooldown;
    // execute skill effect
  }
}

// In update:
