  if (skill.onCooldown) {
    skill.cooldownTimer -= delta;
    if (skill.cooldownTimer <= 0) {
      skill.onCooldown = false;
    }
  }
}

// On stance switch:
function switchStance(newStance) {
  if (player.currentStance !== newStance) {
    applyStanceStats(player, newStance);
    player.currentStance = newStance;
  }
}

function applyStanceStats(entity, stance) {
  if (stance === 'defensive') {
    entity.defense += 10;
    entity.attack -= 5;
  } else if (stance === 'aggressive') {
    entity.defense -= 5;
    entity.attack += 10;
  }
}

