// Capturing logic:
function captureNode(node, faction) {
  node.captureProgress += faction.captureSpeed * delta;
  if (node.captureProgress >= node.captureThreshold) {
    node.owner = faction;
    node.captureProgress = 0;
  }
}

// Resource generation:
if (node.owner) {
  node.owner.resources += node.resourceRate * delta;
}

// On dealing damage:
function onDealDamage(damage) {
  player.focusGauge = Math.min(player.focusGauge + damage * 0.1, player.maxFocus);
  if (player.focusGauge === player.maxFocus) {
    player.canOverdrive = true;
  }
}

